check:
{v:'VER',what:'the cloud review (finding 26), the shield affix: a blast from player 2 (a frag, the air strike, the screen clear) is sent as a blast and the host applies it past the shield and without counting it as a pinning round, while his rounds still meet the shield',
 run:function(){
   if(!window.__deploy||!window.__endRaid||typeof NET!=='object'||!NET||typeof netShotTake!=='function'||typeof netShotSend!=='function'||typeof netEntsInit!=='function'||typeof affixApply!=='function'||typeof pwrPulse!=='function'||typeof mkSentry!=='function'||typeof mkRaider!=='function') return 'SKIP: no raid, party or shield here';
   var NK={}, k, bad=[], g=null, p=null, all=null, oSend=netSend, cap=[], pa={state:'in',seat:1}, E=null, R=null, r, m, s0, hp0, oPX=0, oPY=0, txt, needles, i;
   for(k in NET) NK[k]=NET[k];
   try{
     NET.on=false; NET.role=null; NET.peers=[];
     __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __cleanProfile(); __deploy({kit:[],safe:null,mapIx:0,seed:4242});
     g=__state(); if(!g||g.over||!g.player) return 'SKIP: no live raid';
     p=g.player; all=g.ents.slice(); oPX=p.x; oPY=p.y;
     E=mkSentry(p.x+60,p.y); E.elite=1; E.hp=E.maxhp; E.state='patrol'; E.alert=0; E.affix=null; affixApply(E,0);
     R=mkRaider(p.x-60,p.y,undefined,true); R.elite=0; R.hostile=true; R.state='loot'; R.downed=0; R.hp=R.maxhp; R.merc=0; R.supp=0; R.pinT=0;
     g.ents=all.concat([E,R]); render2D(0.016);
     // THE HOST takes a round and a blast from seat 1
     NET.on=true; NET.role='host'; NET.seat=0; NET.peers=[pa]; NET.up=[]; NET.upSeed=g.seed>>>0;
     if(!netEntsHost()) return 'SKIP: staging: the window does not read as the host';
     netEntsInit(g);
     netSend=function(q,w){ cap.push(w); return true; };
     E.shieldHp=100; hp0=E.hp; s0=E.shieldHp;
     r=netShotTake(pa,{t:'shot',id:E.nid,dmg:30});
     if(r!=='shot') bad.push('the host did not take a round ('+r+')');
     else if(E.hp!==hp0||E.shieldHp!==70) bad.push('a round from player 2 did not meet the shield (hp '+E.hp+' of '+hp0+', shield '+E.shieldHp+')');
     r=netShotTake(pa,{t:'shot',id:E.nid,dmg:30,bl:1});
     if(r!=='shot') bad.push('the host did not take a blast ('+r+')');
     else if(E.shieldHp!==70) bad.push('a blast from player 2 ate the shield ('+E.shieldHp+')');
     else if(E.hp!==hp0-30) bad.push('a blast from player 2 did not reach the body past the shield (hp '+E.hp+' of '+hp0+')');
     R.supp=0; R.pinT=0; netShotTake(pa,{t:'shot',id:R.nid,dmg:3,bl:1});
     if((R.supp|0)!==0) bad.push('a blast counted as a round that pins a pillager');
     netShotTake(pa,{t:'shot',id:R.nid,dmg:3});
     if((R.supp|0)!==1) bad.push('a round that lands stopped counting for suppression ('+R.supp+')');
     // THE LINKED WINDOW sends the flag on a blast and not on a round
     NET.role='join'; NET.seat=1; NET.upSeed=g.seed>>>0; NET.peers=[{state:'in',seat:0}]; NET.up=[];
     E.nid=E.nid||9101;
     cap.length=0; netShotSend(E,20,0,null,0,'',1); m=cap.length?cap[cap.length-1]:null;
     if(!m||m.t!=='shot') bad.push('no shot word was sent for a blast');
     else if(m.bl!==1) bad.push('the shot word of a blast does not say so ('+m.bl+')');
     cap.length=0; netShotSend(E,20,0,null,0,''); m=cap.length?cap[cap.length-1]:null;
     if(m&&m.bl) bad.push('the shot word of a plain round says it is a blast');
     // the screen clear, run for real on the linked window, sends its kills as blasts
     E.elite=0; E.affix=null; E.shieldHp=0; E.hp=E.maxhp; E.x=p.x+40; E.y=p.y;
     g.ents=[E]; cap.length=0; pwrPulse(p);
     m=cap.filter(function(w){ return w&&w.t==='shot'&&w.id===E.nid; })[0];
     if(!m) bad.push('the screen clear on a linked window sent no shot word for the machine in view');
     else if(m.bl!==1) bad.push('the screen clear word is not marked as a blast');
     // the frag charge and the air strike send theirs the same way (read off the page, the needle is put together here)
     txt=[].slice.call(document.scripts).map(function(sc){ return sc.textContent||''; }).join('\n');
     needles=['netShotSend(e,_fdm,Math.atan2(e.y-f.y,e.x-f.x),null,'+'0,\'\',1)','netShotSend(e,dm,Math.atan2(e.y-q.y,e.x-q.x),null,'+'0,\'\',1)'];
     for(i=0;i<needles.length;i++) if(txt.indexOf(needles[i])<0) bad.push('a blast call is not marked: '+needles[i].slice(0,40));
   }catch(ex){ bad.push('threw: '+(ex&&ex.message||ex)); }
   finally{
     netSend=oSend;
     for(k in NET) if(!(k in NK)) delete NET[k];
     for(k in NK) NET[k]=NK[k];
     try{ var g2=__state(); if(g2){ if(all) g2.ents=all; g2.bullets.length=0; if(g2.player){ g2.player.x=oPX; g2.player.y=oPY; } if(!g2.over){ g2.player.downed=false; g2.player.hp=100; __endRaid('abandon'); } } }catch(_e){}
     __topClear();
   }
   return bad.length?bad.join('; '):null; }},
